#!/usr/bin/env bash
# Losslessness proof for docs/archive/CHANGELOG-through-2026-01-01.md — generated by methodology_trim.py v1.8.2.
#
# Self-contained and FROZEN: it embeds the record grammar it was written against, so a later change
# to the trimmer cannot silently change what this shard's proof means. Re-derives L1 (records-zone
# concatenation), L2 (zone pinning) and L3 (record partition). Exits non-zero on failure.
# Run it; do not trust a digest. The last hand-published digest for this repo is not reproducible
# from the artifacts it describes, which is the whole reason this file exists.
#
# NOTE: file contents are read by python, never through $(...) — command substitution strips
# trailing newlines, which silently truncates the LAST record and fails L1/L3 on a correct trim.
# That is not hypothetical: it is what the first version of this script did.
set -u
cd "$(git rev-parse --show-toplevel)" || exit 3
LIVE=CHANGELOG.md
SHARD=docs/archive/CHANGELOG-through-2026-01-01.md
# The walk that finds the trim commit. An EMPTY answer means the shard is not in history yet (an
# uncommitted trim, which the script below proves against HEAD). A walk that FAILS is a different
# thing: with stderr discarded and the failure ignored it read as "empty", and a committed trim was
# "proved" against a working tree that equals HEAD and printed OK having compared nothing.
TRIM_SHA="$(git log --diff-filter=A -1 --format=%H -- "$SHARD" 2>/dev/null)" || {
    echo "verify: cannot walk the history for $SHARD -- the proof did not finish; this is not a verdict (exit 3)" >&2
    exit 3
}
export LIVE SHARD TRIM_SHA
# -I (isolated): no working directory on sys.path and no PYTHON* environment. This script reads the
# tree it checks, and a plain `python3 -` would import a difflib.py or subprocess.py planted at
# the repository root and still end at exit 0. Standard library only, so nothing needs the path.
python3 -I - <<'PYEOF_VERIFY'
import difflib, os, re, subprocess, sys
from collections import Counter

RECORD_KIND = "heading"
RECORD_START = r"^### \d{4}-\d{2}-\d{2} · \["
FENCE_INFO = ""
FOOTER_MODE = "separator"
PREFIX = "../../"

# BL-27 fix 1: the same declared front-matter fields assert_L2's reversal exception already knows
# about (design's regenerated-field table), so a line that changed ONLY inside one of these spans
# is not "lost" — every OTHER line still must survive verbatim, unchanged from before this fix.
REGEN_PATTERNS = []
REGEN = [re.compile(p) for p in REGEN_PATTERNS]

# Issue #93: what a PENDING STUB looks like in this ledger, or '' when it declares none. A frozen
# script cannot consult the trimmer's ledger table, so the marker travels here, beside REGEN. It
# decides only how a failing frontier edit is LABELLED (below); it never turns a failure into a pass.
STUB_PATTERN = ''
STUB = re.compile(STUB_PATTERN, re.M) if STUB_PATTERN else None

FENCE = re.compile(r"^(`{3,}|~{3,})(.*)$")
LINK = re.compile(r"\]\(([^)\s]*)\)")
SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.\-]*:")


def scan(lines):
    marker = None
    for i, raw in enumerate(lines):
        s = raw.rstrip("\r\n")
        inside = marker is not None
        m = FENCE.match(s)
        info = ""
        if marker is None:
            if m:
                marker = (m.group(1)[0], len(m.group(1)))
                info = m.group(2).strip()
        else:
            ch, n = marker
            if m and m.group(1)[0] == ch and len(m.group(1)) >= n and m.group(2).strip() == "":
                marker = None
        yield i, s, inside, info


def spans(line):
    r = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == "`":
            j = i
            while j < n and line[j] == "`":
                j += 1
            t = j - i
            k = j
            while k < n:
                if line[k] == "`":
                    mm = k
                    while mm < n and line[mm] == "`":
                        mm += 1
                    if mm - k == t:
                        r.append((i, mm))
                        i = mm
                        break
                    k = mm
                else:
                    k += 1
            else:
                break
            continue
        i += 1
    return r


def indomain(t):
    return bool(t) and not SCHEME.match(t) and not t.startswith(("#", "/", "../"))


def maplinks(text, fn):
    lines = text.splitlines(keepends=True)
    out = []
    for i, s, inside, _info in scan(lines):
        raw = lines[i]
        if inside or FENCE.match(s):
            out.append(raw)
            continue
        sp = spans(raw)

        def repl(m):
            if any(a <= m.start() < b for a, b in sp):
                return m.group(0)
            new = fn(m.group(1))
            return m.group(0) if new is None else "](" + new + ")"

        out.append(LINK.sub(repl, raw))
    return "".join(out)


def invert(text):
    def back(t):
        if not t.startswith(PREFIX):
            return None
        s = t[len(PREFIX):]
        return s if indomain(s) else None
    return maplinks(text, back)


def zones(text):
    lines = text.splitlines(keepends=True)
    starts, hrs = [], []
    for i, s, inside, info in scan(lines):
        if inside:
            continue
        if RECORD_KIND == "heading" and re.match(RECORD_START, s):
            starts.append(i)
        elif RECORD_KIND == "fence" and info == FENCE_INFO:
            starts.append(i)
        if s.strip() == "---":
            hrs.append(i)
    if not starts:
        return "".join(lines), [], ""
    foot = len(lines)
    if FOOTER_MODE == "separator":
        for i in [h for h in hrs if h > starts[-1]]:
            if "".join(lines[i + 1:]).strip():
                foot = i
                break
    recs = []
    for k, st in enumerate(starts):
        en = starts[k + 1] if k + 1 < len(starts) else foot
        recs.append("".join(lines[st:en]))
    return "".join(lines[:starts[0]]), recs, "".join(lines[foot:])


def unfinished(why):
    # An abort BEFORE the checks is not a verdict. `sys.exit("<text>")` prints the text and exits
    # 1, which is this script's FAIL code, so a proof that had compared nothing read as a trim that
    # lost something. Exit 3 is "the proof did not finish": the code the shell head above uses when
    # it cannot reach the repository root, and the code `--reverify`'s legend gives this case. It
    # is for a ref or an object this clone CANNOT READ, and for nothing else -- see `absent`.
    sys.stderr.write("verify: %s -- the proof did not finish; this is not a verdict (exit 3)\n"
                     % why)
    sys.exit(3)


def absent(why):
    # The opposite mistake, and the worse one: a path that is not in a commit (or a working tree)
    # the proof CAN read is a finding about the trim, not a failure to run. A trim commit that also
    # deletes the live ledger leaves exactly this, and "did not finish" would call a total loss
    # "no verdict". The FAIL code, with the reason as a FAIL line (1.5.0 exited 1 here too).
    print("FAIL: %s" % why)
    sys.exit(1)


def show(ref, path):
    # Three questions, in this order, because they have three different answers. Can the commit
    # be read at all (a shallow clone lacks the trim commit's parent)? Can its tree be read, and
    # does the path appear in it? Can the blob be read (a partial clone fetches it on demand)?
    # Only the first and the third are "did not finish"; a path missing from a readable tree is a FAIL.
    if subprocess.run(["git", "rev-parse", "--verify", "-q", ref + "^{commit}"],
                      stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
        unfinished("cannot read %s:%s" % (ref, path))
    tree = subprocess.run(["git", "ls-tree", "--name-only", ref, "--", path], stdout=subprocess.PIPE,
                          stderr=subprocess.DEVNULL)
    if tree.returncode:
        unfinished("cannot read the tree of %s (for %s)" % (ref, path))
    if not tree.stdout.strip():
        absent("%s is absent from %s, a commit this clone can read: there is nothing to account "
               "for the records against" % (path, ref))
    p = subprocess.run(["git", "show", "%s:%s" % (ref, path)], stdout=subprocess.PIPE,
                       stderr=subprocess.DEVNULL)
    if p.returncode:
        unfinished("cannot read %s:%s" % (ref, path))
    return p.stdout.decode("utf-8")


def readf(path):
    try:
        with open(path, "r", encoding="utf-8", newline="") as fh:
            return fh.read()
    except FileNotFoundError:
        absent("%s does not exist in the working tree" % path)
    except OSError as e:
        unfinished("cannot read %s (%s)" % (path, e.strerror or e))


LIVE, SHARD = os.environ["LIVE"], os.environ["SHARD"]
TRIM = os.environ["TRIM_SHA"]
if TRIM:
    before, after, shard = show(TRIM + "^", LIVE), show(TRIM, LIVE), show(TRIM, SHARD)
    origin = "the trim commit " + TRIM[:7]
else:
    before, after, shard = show("HEAD", LIVE), readf(LIVE), readf(SHARD)
    origin = "HEAD vs the working tree (trim not yet committed)"

bfront, br, bfoot = zones(before)
afront, ar, afoot = zones(after)
sfront, sr, _sfoot = zones(shard)
sr_inv = [invert(r) for r in sr]
fails = []
ran = []


def anchor(rec):
    # The record's own first content line — its heading for a heading-kind ledger, its first
    # key: value line for a fence-kind one. Used only to LABEL records in the report; nothing
    # below decides pass or fail from it.
    for ln in rec.splitlines():
        s = ln.rstrip()
        if s.strip() and not FENCE.match(s):
            return s.strip()
    return ""


# --- What the TRIM COMMIT introduced, MEASURED rather than assumed (BL-36) -------------------
#
# This script re-derives from git at commit granularity, and a commit may legitimately carry more
# than the trim: this repository's own close-out practice writes the trim's ledger entry, that
# session's other entries, and the archive move in one commit. Those extra records are new
# content. They were never in `before`, so they make no claim whatsoever about whether an
# archived record survived — and they must not be able to fail a losslessness proof.
#
# The shipped versions of this script skipped them POSITIONALLY, via a constant `INJECTED` baked
# in at generation time as `1 if trims_the_ledger else 0`. That is a 0/1 flag, not a count: it is
# structurally incapable of modelling a commit that lands two records instead of one, so every
# bundled trim failed by construction with zero data loss. Four of this repo's six shipped proofs
# failed exactly that way while an independent identity-keyed re-derivation measured 0 records
# missing at every trim (docs/audits/2026-08-15-bl36-archive-losslessness.md).
#
# So the injected set is measured HERE, from record content: the records present in
# `after + shard` and absent from `before`. This is a different function of the same three
# artifacts — never the difference L1/L3 are about to assert on — so it cannot make those
# assertions vacuous: delete an archived record and it is missing from `have` no matter what else
# the commit added. Occurrences are removed one-for-one, preserving order, so L1 still compares
# bytes in sequence and a REORDER is still a failure.
#
# It deliberately does NOT excuse a record EDITED inside the trim commit. Such a record's
# pre-trim bytes exist nowhere afterwards; it is reported as MISSING and the proof stays red,
# which is BL-27's judgement and is still correct — a real loss has that same shape.
# NAMES: `absent_records` / `added_records`, not the obvious `missing` / `added`. This is a flat
# script -- every binding here is a module global -- and L2's front-matter clause below already
# binds `missing` for its own, unrelated meaning (front-matter LINES that vanished). Calling this
# one `missing` silently rebinds it before L3 reads it, and because L2 usually finds nothing the
# rebind is to [], so L3 skips its own clause and reports a downstream symptom instead. That is
# not hypothetical: it is what the first build of this fix did, and the narrowed loss control
# caught it. Anything added here needs the same namespace check.
have = Counter(ar) + Counter(sr_inv)
added_records = list((have - Counter(br)).elements())
absent_records = list((Counter(br) - have).elements())


def drop_added(seq, remaining):
    out = []
    for r in seq:
        if remaining.get(r, 0) > 0:
            remaining[r] -= 1
        else:
            out.append(r)
    return out


still_to_drop = dict(Counter(added_records))
ar_cmp = drop_added(ar, still_to_drop)
sr_cmp = drop_added(sr_inv, still_to_drop)

# --- L1: records-zone concatenation ---------------------------------------------------------
ran.append("L1")
rebuilt = ar_cmp + sr_cmp
if "".join(rebuilt) != "".join(br):
    fails.append("L1 records-zone concatenation is not byte-identical")

# --- L2: zone pinning. BOTH halves — footer AND front matter. -------------------------------
# The footer half is conditional (a ledger may legitimately have no footer); the front-matter
# half is not, and its absence is why an earlier version of this script printed "L1, L2 and L3
# hold" after running zero L2 assertions on both of this repo's real ledgers.
if bfoot.strip():
    ran.append("L2/footer")
    if afoot != bfoot:
        fails.append("L2 FOOTER is not byte-identical in the live file")
    if bfoot.strip() in shard or bfoot.strip() in invert(shard):
        fails.append("L2 FOOTER migrated into the shard")

ran.append("L2/front-matter")
# Front matter may GAIN declared blocks (the shard pointer, a new month heading); it may not lose
# or reword anything. Every non-blank line of the original must survive verbatim in the new front
# matter, and none of it may have travelled into the shard — UNLESS the only change is confined to
# a declared regenerated field's own value (BL-27 fix 1), the same exception assert_L2 already
# applies via its reversal loop. This is a narrower carve-out than assert_L2's, on purpose: it
# excuses a specific LINE only when it has a same-shaped partner line in the new front matter with
# identical bytes everywhere outside the declared span — an actual reword just outside the field's
# own parens still fails, same as an edit anywhere else in front matter.
def field_reversible(missing_line):
    for rx in REGEN:
        m = rx.search(missing_line)
        if not m:
            continue
        prefix, suffix = m.group(1), m.group(3)
        residue = missing_line[:m.start()] + missing_line[m.end():]
        for al in afront.splitlines():
            am = rx.search(al)
            if (am and am.group(1) == prefix and am.group(3) == suffix
                    and al[:am.start()] + al[am.end():] == residue):
                return True
    return False


# BL-28 fix: exact-line-set membership, not substring containment. `ln not in afront` tested
# whether `ln` occurs anywhere in the whole front-matter TEXT — an append-style edit that keeps
# the original line as a literal prefix of a new, longer line leaves that substring intact and
# reads as "found," so a real change to the line evaded detection. Comparing against the SET of
# exact lines in the new front matter closes that gap without touching field_reversible's own
# separate, correct line-by-line carve-out for the declared regenerated fields.
afront_lines = set(afront.splitlines())
missing = [ln for ln in bfront.splitlines()
           if ln.strip() and ln not in afront_lines and not field_reversible(ln)]
if missing:
    fails.append("L2 FRONT MATTER lost %d line(s), first: %r" % (len(missing), missing[0][:70]))
# Issue #93 fix: whole-line membership, not substring containment. `ln in sfront` and
# `ln in "".join(sr)` asked whether the front-matter line occurs ANYWHERE in the shard's text,
# so an archived record that merely QUOTED it mid-line (in backticks, in a longer line) read as
# the line having travelled into the shard. A migration moves WHOLE lines, so the test is
# membership in the sets of whole lines of the shard's front matter and of its records; the
# `> 24` length filter is kept. Same class of fix as BL-28 just above, on the other clause.
sfront_lines = set(sfront.splitlines())
sr_lines = set("".join(sr).splitlines())
leaked = [ln for ln in bfront.splitlines()
          if ln.strip() and len(ln.strip()) > 24 and (ln in sfront_lines or ln in sr_lines)]
if leaked:
    fails.append("L2 FRONT MATTER leaked %d line(s) into the shard, first: %r"
                 % (len(leaked), leaked[0][:70]))

# --- L3: record partition ---------------------------------------------------------------------
ran.append("L3")
bad = None
if absent_records:
    # The only way a record from `before` fails to appear in `after + shard`: it was dropped, or
    # it was edited (in which case its pre-trim bytes are gone and an edited twin shows up in
    # `added_records`). Both are real; neither is excused. A count mismatch cannot occur here
    # without this firing first — len(rebuilt) is len(br) - len(absent_records) by construction —
    # so there is no separate count clause to state, and none that could ever run.
    fails.append("L3 %d record(s) present before the trim are MISSING from live+shard afterwards"
                 % len(absent_records))
else:
    bad = [i for i, (x, y) in enumerate(zip(br, rebuilt)) if x != y]
    if bad:
        fails.append("L3 record(s) out of order across the move: %s" % bad)

# BL-27 fix 2: a same-commit close-out bundling (a session's own frontier receipt going
# status: pending -> complete, committed together with the archive write) makes position 0 (newest)
# differ between this commit's parent and itself. That bundling is NOT this framework's practice --
# FRAMEWORK_APPARATUS.md says a trim earns its own commit, and issue #93 measured what it costs --
# but sessions have done it, so the proof must still judge it. NOT an exemption: this stays a FAIL,
# loud, because a real loss can have this exact shape too -- only a NOTE naming the pattern, so a
# reader does not mistake it for an unqualified loss. Narrow on purpose: any OTHER record differing
# (bad != [0]) gets no such note.
#
# BL-36 re-expressed the gate in the new vocabulary. It was `bad == [0]` — the record-ALTERED
# shape under the old positional comparison — which is why it never fired for the busier ledger,
# whose bundling produced a count mismatch instead and so failed with no explanation at all
# (audit Finding #4). Additions no longer fail, so that half is gone; what remains is the edit,
# which now presents as exactly one MISSING record that was the frontier, paired with an added
# record carrying the same anchor. Still narrow on purpose: an edit to any other record, or one
# whose anchor changed, gets no such note.
notes = []
frontier_edit = (len(absent_records) == 1 and br and absent_records[0] == br[0]
                 and anchor(absent_records[0]) != ""
                 and any(anchor(a) == anchor(absent_records[0]) for a in added_records))

# Issue #93, cause 1: ONE shape of frontier edit can be NAMED rather than merely noted -- a pending
# stub that this commit finalized. The discriminator is not a guess: it is every one of (a) the
# frontier edit above, (b) the pre-trim record 0 matches the ledger's declared stub marker, (c) the
# record that replaced it no longer does (an edit made while still pending was not a finalize),
# (d) nothing else failed, and (e) the OTHER records are byte-identical and still in order. A stub
# is a claim placeholder meant to be replaced, so what its replacement removed was never data. Any
# one missing and the edit keeps the generic note and exit 1, which is what BL-27 protected: a
# record 0 that was COMPLETE before the trim and differs after it is a real-loss shape.
stub_finalized = False
successor = (next(a for a in added_records if anchor(a) == anchor(absent_records[0]))
             if frontier_edit else None)
# Everything but record 0 is byte-identical and in order across the move. The stub label needs it
# (e), and so does everything below that speaks about record 0 ALONE: the frontier note and the
# diff. Without it an edit to record 0 that also reordered or changed other records printed the
# reassuring note and a diff of record 0 and said nothing of the rest.
others_intact = (rebuilt == br[1:])
if fails and frontier_edit and STUB is not None and STUB.search(absent_records[0]):
    other_fails = [f for f in fails if not (f.startswith("L1 ") or f.startswith("L3 "))]
    stub_finalized = (not STUB.search(successor) and not other_fails and others_intact)

if stub_finalized:
    # The generic L1/L3 pair is this edit's own symptom (record 0's pre-trim bytes are the stub, and
    # they exist nowhere afterwards), and (d) and (e) established nothing else is wrong, so the label
    # REPLACES the pair instead of sitting beside it. Still a FAIL: exit 4, never 0 -- labelled, not excused.
    fails[:] = [f for f in fails if not (f.startswith("L1 ") or f.startswith("L3 "))]
    fails.append("record 0 was a pending stub (%d B) and was finalized in the trim commit; the "
                 "other %d record(s) are byte-identical across the move, in order, and L2 holds"
                 % (len(absent_records[0].encode("utf-8")), len(br) - 1))
    notes.append(
        "exit 4, not 1: a recognised stub finalize is NAMED, but it is still a FAIL, because a "
        "real loss can have this exact shape too. The proof certifies that nothing but record 0 "
        "changed and that record 0 was a stub; it cannot certify that the finalized text is right. "
        "To avoid it, give the trim a commit of its own, never in the same commit that edits record 0.")
elif fails and frontier_edit and not others_intact:
    notes.append(
        "record 0 was edited AND the other record(s) are not byte-identical and in order across the "
        "move (they were reordered, edited or dropped as well), so this is not the shape a bundled "
        "finalize leaves and no diff of record 0 is shown: it would hide the rest. Compare the "
        "shard's records against the parent's by hand.")
elif fails and frontier_edit:
    notes.append(
        "the only missing record is the frontier one (position 0, newest), and an added record "
        "carries the same anchor -- the shape (BL-27) a bundled finalize leaves: record 0 was "
        "edited in the same commit as the archive write, so it differs between this commit's "
        "parent and itself. That bundling is not this framework's practice: give the trim a commit "
        "of its own, never in the same commit that edits record 0. This does NOT confirm "
        "losslessness -- a real loss can have this exact "
        "shape -- so diff record 0 by hand to be sure it is a finalize and not data loss."
        + ("" if STUB is not None else
           " This ledger declares no stub marker, so a pending-stub finalize cannot be told from "
           "any other edit of record 0."))

print("source : %s" % origin)
print("records: %d before = %d retained + %d archived; added by the trim commit: %d"
      % (len(br), len(ar_cmp), len(sr_cmp), len(added_records)))
for m in absent_records:
    print("   MISSING: %s" % anchor(m)[:100])
for a in added_records:
    print("   added  : %s" % anchor(a)[:100])
print("checked: %s" % ", ".join(ran))
for f in fails:
    print("FAIL:", f)
for n in notes:
    print("NOTE:", n)
if frontier_edit and others_intact:
    # Issue #93's first suggestion. The proof cannot judge an edit to record 0 -- a stub finalize and
    # a real loss have the same shape -- but a reader shown the edit can, in seconds. Printed for both
    # shapes the frontier note covers (the recognised stub finalize, exit 4, and the generic edit,
    # exit 1) and for nothing else: a record other than the frontier that differs is a plain loss,
    # and a diff would dress it up -- so is a frontier edit with other records moved as well, where
    # a diff of record 0 alone would hide the rest. Output only; it changes no verdict and no exit
    # status.
    diff = list(difflib.unified_diff(absent_records[0].splitlines(keepends=True),
                                     successor.splitlines(keepends=True),
                                     fromfile="record 0 before the trim commit (its parent)",
                                     tofile="record 0 in the trim commit"))
    print("DIFF: record 0, before the trim commit (-) against the record that replaced it (+), "
          "%d line(s):" % len(diff))
    for ln in diff:
        sys.stdout.write(ln if ln.endswith("\n") else ln + "\n")
if fails:
    sys.exit(4 if stub_finalized else 1)
# State what actually ran, never a blanket claim: on a ledger with no footer the footer clause is
# genuinely inapplicable, and saying "L2 holds" would be asserting something nothing tested.
print("OK: %s hold for %s" % (", ".join(ran), SHARD))
PYEOF_VERIFY
